function check([operations, args], actual, expected) {
  if (!Array.isArray(actual) || actual.length !== operations.length || actual[0] !== null) return false;
  const counts = new Map();
  let size = 0;
  let run = [];
  let ok = true;
  // A long run of getRandom on an unchanged collection must roughly follow each value's share of copies.
  const flush = () => {
    if (run.length >= 300) {
      for (const [value, copies] of counts) {
        if (copies === 0) continue;
        const p = copies / size, n = run.length;
        const seen = run.filter(v => v === value).length;
        if (Math.abs(seen - n * p) > 7 * Math.sqrt(n * p * (1 - p)) + 5) ok = false;
      }
    }
    run = [];
  };
  for (let i = 1; i < operations.length && ok; i++) {
    const op = operations[i], out = actual[i];
    if (op === 'insert') {
      flush();
      const had = counts.get(args[i][0]) || 0;
      if (out !== (had === 0)) return false;
      counts.set(args[i][0], had + 1);
      size++;
    } else if (op === 'remove') {
      flush();
      const had = counts.get(args[i][0]) || 0;
      if (out !== (had > 0)) return false;
      if (had > 0) { counts.set(args[i][0], had - 1); size--; }
    } else {
      if (typeof out !== 'number' || !(counts.get(out) > 0)) return false;
      run.push(out);
    }
  }
  flush();
  return ok;
}

