function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must have the same length.';
  if (operations[0] !== 'RandomizedCollection' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with RandomizedCollection and no arguments.';
  if (operations.length - 1 > 200000) return 'At most 2 * 10^5 calls are allowed.';
  let size = 0;
  const counts = new Map();
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i], arg = args[i];
    if (op === 'insert' || op === 'remove') {
      if (!Array.isArray(arg) || arg.length !== 1 || !Number.isInteger(arg[0])) return `${op} takes one integer.`;
      if (arg[0] < -2147483648 || arg[0] > 2147483647) return 'Each val fits in a 32-bit signed integer.';
      const had = counts.get(arg[0]) || 0;
      if (op === 'insert') { counts.set(arg[0], had + 1); size++; }
      else if (had > 0) { counts.set(arg[0], had - 1); size--; }
    } else if (op === 'getRandom') {
      if (!Array.isArray(arg) || arg.length !== 0) return 'getRandom takes no arguments.';
      if (size === 0) return 'getRandom needs at least one item in the collection.';
    } else return `Unknown operation ${op}.`;
  }
  return null;
}

