class RandomizedCollection {
  constructor() {
    this.values = [];
    this.positions = new Map();
  }

  insert(val) {
    if (!this.positions.has(val)) {
      this.positions.set(val, new Set());
    }
    const slots = this.positions.get(val);
    slots.add(this.values.length);
    this.values.push(val);
    return slots.size === 1;
  }

  remove(val) {
    const slots = this.positions.get(val);
    if (!slots) {
      return false;
    }
    const index = slots.values().next().value;
    slots.delete(index);
    const lastIndex = this.values.length - 1;
    const lastValue = this.values[lastIndex];
    this.values[index] = lastValue;
    const lastSlots = this.positions.get(lastValue);
    lastSlots.add(index);
    lastSlots.delete(lastIndex);
    this.values.pop();
    if (slots.size === 0) {
      this.positions.delete(val);
    }
    return true;
  }

  getRandom() {
    const index = Math.floor(Math.random() * this.values.length);
    return this.values[index];
  }
}

