function generate(rand, size) {
  const count = size === 'large' ? 499 : 1 + Math.floor(rand() * 16);
  const extremes = [-2147483648, 2147483647, 0];
  const pool = size === 'large'
    ? Array.from({ length: 40 }, () => Math.floor(rand() * 4294967296) - 2147483648)
    : rand() < 0.2 ? extremes : [-2, -1, 0, 1, 2].slice(0, 2 + Math.floor(rand() * 4));
  const operations = ['RandomizedCollection'], args = [[]];
  const counts = new Map();
  let total = 0;
  for (let i = 0; i < count; i++) {
    const roll = rand(), val = pool[Math.floor(rand() * pool.length)];
    if (roll < 0.25 && total > 0) {
      operations.push('getRandom'); args.push([]);
    } else if (roll < 0.6) {
      operations.push('remove'); args.push([val]);
      if (counts.get(val)) { counts.set(val, counts.get(val) - 1); total--; }
    } else {
      operations.push('insert'); args.push([val]);
      counts.set(val, (counts.get(val) || 0) + 1); total++;
    }
  }
  return [operations, args];
}
